#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string text;
    cout << "Enter a sentence: ";
    getline(cin, text);

    int vowels = 0, consonants = 0, digits = 0, spaces = 0;
    string vowelSet = "aeiouAEIOU";

    for (char c : text) {
        if (isspace(c)) spaces++;
        else if (isdigit(c)) digits++;
        else if (isalpha(c)) {
            if (vowelSet.find(c) != string::npos) vowels++;
            else consonants++;
        }
    }

    cout << "Vowels: " << vowels << endl;
    cout << "Consonants: " << consonants << endl;
    cout << "Digits: " << digits << endl;
    cout << "Spaces: " << spaces << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[2][2], b[2][2], sum[2][2], prod[2][2] = {0};

    cout << "Enter matrix A (4 numbers): ";
    for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) cin >> a[i][j];

    cout << "Enter matrix B (4 numbers): ";
    for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) cin >> b[i][j];

    cout << "Sum:" << endl;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            sum[i][j] = a[i][j] + b[i][j];
            cout << sum[i][j] << " ";
        }
        cout << endl;
    }

    cout << "Product:" << endl;
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            for (int k = 0; k < 2; k++)
                prod[i][j] += a[i][k] * b[k][j];

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) cout << prod[i][j] << " ";
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double balance;
    int n;
    cout << "Starting balance: ";
    cin >> balance;
    cout << "Number of transactions: ";
    cin >> n;

    double largest = 0;
    for (int i = 0; i < n; i++) {
        double t;
        cin >> t;
        balance += t;
        if (fabs(t) > fabs(largest)) largest = t;
    }

    cout << "Final balance: " << balance << endl;
    cout << "Largest transaction: " << largest << endl;
    return 0;
}

