#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cout << "Number of contacts: ";
    cin >> n;
    string names[100];
    for (int i = 0; i < n; i++) cin >> names[i];

    sort(names, names + n);

    string query;
    cout << "Search for: ";
    cin >> query;

    if (binary_search(names, names + n, query))
        cout << "Found: " << query << endl;
    else
        cout << "Not found." << endl;

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string title = "C++ Basics";
    int totalCopies = 3, available = 3;
    int choice;

    do {
        cout << "\nAvailable copies of \"" << title << "\": " << available << endl;
        cout << "1. Issue 2. Return 3. Exit\nChoice: ";
        cin >> choice;

        if (choice == 1) {
            if (available > 0) { available--; cout << "Issued.\n"; }
            else cout << "No copies available!\n";
        } else if (choice == 2) {
            if (available < totalCopies) { available++; cout << "Returned.\n"; }
            else cout << "All copies already in library!\n";
        }
    } while (choice != 3);

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string word;
    cout << "Enter a word: ";
    cin >> word;
    bool isPalin = true;
    int n = word.length();
    for (int i = 0; i < n / 2; i++) {
        if (word[i] != word[n - 1 - i]) { isPalin = false; break; }
    }
    cout << word << (isPalin ? " is a palindrome" : " is not a palindrome") << endl;
    return 0;
}

